INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1116063-che464', 'stk-azeezo', 'CHE 464', 'info', '{"desc": "انا حاليا اطبق في ارمكو و جلست مع ناس تخرجوا من جامعتنا الموقرة يقولون ان مهم جدا انك تاخذ هذا الكورس\n\nCHE 464 Refining & PetroChem. Tech &\n\nيقولون انه مرتبط حيل بتوجه الشركات النفطية في المملكة\nالاخر انا انصح ب كورس رقم 2 لان بينوص يشرف عليه و دوما اسئلته سهلة اذا كان هو الوحيد على المادة (دوما يعطيك تلميحات تساعدك بالحل )\n\nبالنسبة لتخصصنا (هندسة كيميائية - مع انه غلط نقول كذا لان الأسم الأصح لتخصصنا Process engineer -)\nتخصصنا يتطلب انك تسجل في كل صيفية علشان ترتاح و تجيب معدل وانا اقوك اذا انت مب على حافة من المعدل (يعني احتمال انك تنتقل من 2.48 الى 2.5 او 2.96 الى 3 ) انا اقولك سوي الي يريحك\n\nاما اذا كنت على حافة معدل انا اقترح انك تمدها الى الصيف\nوهذا رأي و آمل اني شرحتها بوضوح\n\n122:\nاوكي خله كذا لان 311 شوي يبيلها كدح (خاصة اذا كنت تتعب مع المذاكرة )\n\n131:\nبرضو الجدول مناسب خاصة انك بعد ما ترجع راح يكون الجدول CHE (يتداول ان 401 اسهل من 402)\n141 :\nمناسب\n\nاذا تقدر تشيل ME افضل لان CHE 201 بتكون اول مواد التخصص يكون حلو لو تركز عليها\n\nالبقية مناسب والله يعينك الأورقانك طويل و يتطلب مهارتي الحفظ والفهم\n\nافضل لو تخلي 101 مع بعضها خاصة انها اسهل من 102 و في حال نزلت ال3 مواد (ماث فيزيا كمستري ) استخدم اسلوب التضحية (يعني خلي مادتين اكثر اهتماما و مادة للتعدية بC او C+)", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/134476/24", "user": "azeezo", "ts": 1352706370000, "tid": 134476, "pn": 24}}', 1352706370000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
